'use strict';

/**
 * Sliding-window rate limiting middleware for Express.
 *
 * This is a TRUE sliding window: every request timestamp is recorded per client,
 * and on each request all timestamps older than `windowMs` are evicted before
 * counting. There is no fixed interval that resets the counter, so a client
 * cannot burst 2x the limit across a window boundary.
 *
 * NOTE ON `req.ip` AND PROXIES:
 * -----------------------------
 * `req.ip` reflects the socket's remote address unless Express is told to trust
 * proxies. If your app runs behind a load balancer, reverse proxy, or CDN
 * (nginx, ELB/ALB, Cloudflare, Heroku, Render, ...), every request will appear
 * to come from the proxy's IP and ALL clients will share a single bucket.
 *
 * Fix it by enabling trust proxy so Express parses `X-Forwarded-For`:
 *
 *     app.set('trust proxy', 1);            // 1 hop: a single known proxy
 *     app.set('trust proxy', 'loopback');   // trust only local proxies
 *     app.set('trust proxy', '10.0.0.0/8'); // trust a specific subnet
 *
 * Do NOT use `app.set('trust proxy', true)` on a publicly reachable server:
 * `X-Forwarded-For` is client-controllable, so an attacker could spoof a new IP
 * per request and bypass the limiter entirely. Trust only the hops you control.
 * If your platform provides a trustworthy header (e.g. Cloudflare's
 * `CF-Connecting-IP`), pass a custom `keyGenerator` instead.
 */

const DEFAULT_WINDOW_MS = 60 * 1000; // 1 minute
const DEFAULT_MAX_REQUESTS = 100;
const CLEANUP_INTERVAL_MS = 60 * 1000; // 60 seconds

/**
 * @param {object}   [options]
 * @param {number}   [options.windowMs=60000]      Window size in milliseconds.
 * @param {number}   [options.maxRequests=100]     Max requests allowed per window.
 * @param {function} [options.keyGenerator]        (req) => string identifying the client.
 * @param {function} [options.skip]                (req) => boolean; true bypasses the limiter.
 * @param {function} [options.onLimitReached]      (req, res, info) => void; called on rejection.
 * @param {string}   [options.message]             Error string in the 429 body.
 * @param {number}   [options.cleanupIntervalMs=60000]  Sweep cadence for idle keys.
 * @returns {function} Express middleware, with a `.close()` method attached.
 */
function createRateLimiter(options = {}) {
  const {
    windowMs = DEFAULT_WINDOW_MS,
    maxRequests = DEFAULT_MAX_REQUESTS,
    keyGenerator = (req) => req.ip,
    skip = () => false,
    onLimitReached = null,
    message = 'Rate limit exceeded',
    cleanupIntervalMs = CLEANUP_INTERVAL_MS,
  } = options;

  if (!Number.isFinite(windowMs) || windowMs <= 0) {
    throw new TypeError('windowMs must be a positive finite number');
  }
  if (!Number.isFinite(maxRequests) || maxRequests < 0) {
    throw new TypeError('maxRequests must be a non-negative finite number');
  }

  /**
   * key -> array of request timestamps (ms epoch), kept in ascending order.
   * Ascending order is guaranteed because we only ever push `Date.now()`,
   * which lets eviction be a single O(k) prefix cut.
   * @type {Map<string, number[]>}
   */
  const hits = new Map();

  /**
   * Drop every timestamp <= cutoff. Timestamps are sorted ascending, so the
   * expired entries are always a prefix; find the first survivor and slice.
   * Mutates `timestamps` in place and returns it.
   */
  function evictExpired(timestamps, cutoff) {
    let firstValid = 0;
    while (firstValid < timestamps.length && timestamps[firstValid] <= cutoff) {
      firstValid++;
    }
    if (firstValid > 0) timestamps.splice(0, firstValid);
    return timestamps;
  }

  function middleware(req, res, next) {
    let bypass = false;
    try {
      bypass = Boolean(skip(req));
    } catch (_err) {
      bypass = false;
    }
    if (bypass) return next();

    let key;
    try {
      key = keyGenerator(req);
    } catch (_err) {
      key = undefined;
    }
    // Fall back to a shared bucket rather than failing open if the IP is
    // unavailable (e.g. socket already destroyed).
    if (key === undefined || key === null || key === '') key = 'unknown';
    key = String(key);

    const now = Date.now();
    const cutoff = now - windowMs; // timestamps at or before this are outside the window

    let timestamps = hits.get(key);
    if (timestamps === undefined) {
      timestamps = [];
      hits.set(key, timestamps);
    }
    evictExpired(timestamps, cutoff);

    if (timestamps.length >= maxRequests) {
      // Oldest surviving timestamp determines when a slot frees up.
      const oldest = timestamps[0];
      const resetAtMs = oldest + windowMs;
      const retryAfterSec = Math.max(1, Math.ceil((resetAtMs - now) / 1000));
      const resetEpochSec = Math.ceil(resetAtMs / 1000);

      res.setHeader('X-RateLimit-Limit', String(maxRequests));
      res.setHeader('X-RateLimit-Remaining', '0');
      res.setHeader('X-RateLimit-Reset', String(resetEpochSec));
      res.setHeader('Retry-After', String(retryAfterSec));

      if (typeof onLimitReached === 'function') {
        try {
          onLimitReached(req, res, { key, limit: maxRequests, retryAfter: retryAfterSec });
        } catch (_err) {
          /* never let a user hook break the response */
        }
      }

      // Do NOT call next() — the request stops here.
      return res.status(429).json({ error: message, retryAfter: retryAfterSec });
    }

    timestamps.push(now);

    const remaining = Math.max(0, maxRequests - timestamps.length);
    // Window slides off the oldest in-window request.
    const resetAtMs = timestamps[0] + windowMs;

    res.setHeader('X-RateLimit-Limit', String(maxRequests));
    res.setHeader('X-RateLimit-Remaining', String(remaining));
    res.setHeader('X-RateLimit-Reset', String(Math.ceil(resetAtMs / 1000)));

    return next();
  }

  // --- Memory management -----------------------------------------------
  // Without this sweep, `hits` grows unbounded: one Map entry per IP ever
  // seen, each holding an empty array long after that client went away.
  const cleanupTimer = setInterval(() => {
    const cutoff = Date.now() - windowMs;
    for (const [key, timestamps] of hits) {
      evictExpired(timestamps, cutoff);
      if (timestamps.length === 0) hits.delete(key);
    }
  }, cleanupIntervalMs);

  // Do not hold the event loop open just for the sweep.
  if (typeof cleanupTimer.unref === 'function') cleanupTimer.unref();

  /** Stop the cleanup timer and release all tracked state. */
  middleware.close = function close() {
    clearInterval(cleanupTimer);
    hits.clear();
  };

  /** Forget one client (e.g. after a successful login). */
  middleware.resetKey = function resetKey(key) {
    return hits.delete(String(key));
  };

  /** Forget every client without stopping the timer. */
  middleware.resetAll = function resetAll() {
    hits.clear();
  };

  /** Live count of tracked keys — handy for tests and metrics. */
  Object.defineProperty(middleware, 'size', { get: () => hits.size });

  return middleware;
}

module.exports = createRateLimiter;
module.exports.createRateLimiter = createRateLimiter;
