/**
 * sliding-window-rate-limiter.js
 *
 * A TRUE sliding window rate limiter for Express.js.
 *
 * Unlike a fixed window (which resets a counter every N ms and can allow up
 * to 2x maxRequests in a burst straddling the reset boundary), this
 * implementation keeps a timestamp log per client and only counts requests
 * that fall within the last `windowMs` milliseconds, computed relative to
 * *now* on every single request. The window "slides" continuously.
 *
 * NOTE on req.ip / proxies:
 *   By default, Express's `req.ip` reflects the direct TCP peer, which is
 *   WRONG if your app sits behind a reverse proxy / load balancer (nginx,
 *   ELB, Cloudflare, etc.) — every request will appear to come from the
 *   proxy's IP, collapsing all clients into one rate-limit bucket.
 *
 *   If you are behind a proxy, you MUST set:
 *     app.set('trust proxy', 1);           // or the correct hop count / CIDR list
 *   so Express parses `X-Forwarded-For` correctly and `req.ip` reflects the
 *   real client. Never blindly trust `X-Forwarded-For` from the public
 *   internet without `trust proxy` configured — it's trivially spoofable
 *   otherwise, letting clients bypass rate limits by sending their own
 *   forged header.
 */

'use strict';

function createRateLimiter(options = {}) {
  const windowMs = options.windowMs || 60000; // 1 minute
  const maxRequests = options.maxRequests || 100;
  const keyGenerator = options.keyGenerator || ((req) => req.ip);
  const cleanupIntervalMs = options.cleanupIntervalMs || 60000; // 60s

  // Map<key, number[]> — sorted ascending array of request timestamps (ms)
  const store = new Map();

  function getTimestamps(key) {
    return store.get(key) || [];
  }

  // Removes timestamps older than the sliding window boundary, mutating
  // in place would require care since arrays are shared; we rebuild instead.
  function pruneOldTimestamps(timestamps, now) {
    const cutoff = now - windowMs;
    // Timestamps are stored in insertion (ascending) order, so we can find
    // the first index still within the window and slice from there —
    // O(k) where k = number of expired entries, not the full array.
    let i = 0;
    while (i < timestamps.length && timestamps[i] <= cutoff) {
      i++;
    }
    return i === 0 ? timestamps : timestamps.slice(i);
  }

  function middleware(req, res, next) {
    const now = Date.now();
    const key = keyGenerator(req);

    let timestamps = getTimestamps(key);
    timestamps = pruneOldTimestamps(timestamps, now);

    const currentCount = timestamps.length;

    if (currentCount >= maxRequests) {
      // Rejected: do NOT record this request's timestamp.
      // Reset time = when the oldest timestamp in the window expires.
      const oldest = timestamps[0];
      const msUntilSlideOpens = oldest !== undefined
        ? (oldest + windowMs) - now
        : windowMs;
      const retryAfterSec = Math.max(1, Math.ceil(msUntilSlideOpens / 1000));

      store.set(key, timestamps); // persist pruned array even on reject

      res.set('Retry-After', String(retryAfterSec));
      res.set('X-RateLimit-Limit', String(maxRequests));
      res.set('X-RateLimit-Remaining', '0');
      res.set('X-RateLimit-Reset', String(Math.ceil((now + msUntilSlideOpens) / 1000)));

      return res.status(429).json({
        error: 'Rate limit exceeded',
        retryAfter: retryAfterSec,
      });
    }

    // Allowed: record this request's timestamp.
    timestamps.push(now);
    store.set(key, timestamps);

    const remaining = Math.max(0, maxRequests - timestamps.length);
    // Reset = when the *current* oldest timestamp (timestamps[0]) falls out
    // of the window — i.e. when the count would next decrease.
    const resetAtMs = timestamps[0] + windowMs;

    res.set('X-RateLimit-Limit', String(maxRequests));
    res.set('X-RateLimit-Remaining', String(remaining));
    res.set('X-RateLimit-Reset', String(Math.ceil(resetAtMs / 1000)));

    next();
  }

  // Periodic cleanup: drop keys whose entire timestamp log has expired,
  // so idle clients don't leak memory forever.
  const cleanupTimer = setInterval(() => {
    const now = Date.now();
    for (const [key, timestamps] of store.entries()) {
      const pruned = pruneOldTimestamps(timestamps, now);
      if (pruned.length === 0) {
        store.delete(key);
      } else if (pruned.length !== timestamps.length) {
        store.set(key, pruned);
      }
    }
  }, cleanupIntervalMs);

  // Don't let the cleanup timer keep the Node process alive by itself.
  if (typeof cleanupTimer.unref === 'function') {
    cleanupTimer.unref();
  }

  middleware.close = function close() {
    clearInterval(cleanupTimer);
  };
  // Alias, in case callers prefer this name.
  middleware.stop = middleware.close;

  // Exposed for tests/introspection only — not part of the public contract.
  middleware._store = store;

  return middleware;
}

module.exports = { createRateLimiter };
